@pytest.mark.parametrize('changed', [True, False], ids=['changed-source', 'matching-control']) def test_real_crash_resume_pins_exported_executor(tmp_path, changed): root, job = make_fixture(tmp_path, 'valid') store = durable.Store.create(tmp_path / 'state.db', [job], root) source = Path(durable.__file__).resolve().parent for label in ['a', 'b']: shutil.copytree(source, tmp_path / label / 'vare', ignore=shutil.ignore_patterns('__pycache__')) if changed: with (tmp_path / 'b/vare/runner.py').open('a') as stream: stream.write("\nSOURCE_PIN_DIAGNOSTIC = 'runtime-b'\n") script = '''import asyncio,hashlib,json,os,pathlib,sys from vare import runner from vare.durable import Store,worker,audit_durable store=Store(sys.argv[1]); mode=sys.argv[2] if mode=='crash': claim=store.claim('lost-owner',.2) print(json.dumps({'token':claim['token']}),flush=True) os._exit(42) result={'used_runner_sha256':hashlib.sha256(pathlib.Path(runner.__file__).read_bytes()).hexdigest(), 'loaded_marker':getattr(runner,'SOURCE_PIN_DIAGNOSTIC',None)} try: asyncio.run(worker(store,'replacement',2)) except ValueError as exc: result.update(status='refused',error_type=type(exc).__name__,message=str(exc)) else: result['status']='completed' output=pathlib.Path(sys.argv[3]);store.export(output) result['audit']=audit_durable(output) result['exported_runner_sha256']=hashlib.sha256((output/'snapshot/vare/runner.py').read_bytes()).hexdigest() result['token']=store.jobs()[0]['token'] print(json.dumps(result),flush=True) sys.exit(17 if result['status']=='refused' else 0) ''' records = [] evidence = os.environ.get('VARE_RUNTIME_SOURCE_EVIDENCE_DIR') label = 'changed-source' if changed else 'matching-control' try: for runtime, mode, output in [('a', 'crash', 'unused'), ('b', 'resume', 'after-b')]: process = subprocess.run([sys.executable, '-c', script, str(store.path), mode, str(tmp_path / output)], cwd=tmp_path, env={**os.environ, 'PYTHONPATH': str(tmp_path / runtime), 'PYTHONDONTWRITEBYTECODE': '1'}, capture_output=True, text=True, timeout=15) records.append({'runtime': runtime, 'mode': mode, 'exit_code': process.returncode, 'stdout': process.stdout, 'stderr': process.stderr}) assert records[0]['exit_code'] == 42 resumed = json.loads(records[1]['stdout']) > assert records[1]['exit_code'] == (17 if changed else 0), resumed E AssertionError: {'audit': {'attempts': 2, 'events': 5, 'jobs': 1, 'outcomes': {'candidate_passed': 1}, ...}, 'exported_runner_sha256':...6ce099dbc262c7c622336d77828b90fa73af9e436664f24c391ad7aa391', 'loaded_marker': 'runtime-b', 'status': 'completed', ...} E assert 0 == 17
